// catalog · кейсы cat-13, cat-03 (buyer) (.qa/tests/catalog/) — לקוח עסקי: нет доступа к управлению каталогом, нет «יחידת מכירה».
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/buyer.json') });

test.describe('catalog — לקוח עסקי', () => {
  for (const url of ['/catalog', '/catalog/new', '/catalog/categories']) {
    test(`לקוח לא נכנס ל-${url} — הפניה ל-/shop #6a38cf5d #6a38cf5e @desktop @prod-safe`, async ({ page }) => {
      await page.goto(url);
      await expect(page).toHaveURL(/\/shop$/, { timeout: 20_000 });
      await expect(page.getByRole('searchbox', { name: 'חיפוש מוצר' })).toBeVisible();
      await expect(page.getByRole('heading', { name: /קטלוג וניהול|מוצר חדש|קטגוריות/ })).toHaveCount(0);
    });
  }

  test('דף מוצר אצל הלקוח — בלי «יחידת מכירה» / מארזים, כמות מספרית #6a858d3f @desktop @prod-safe', async ({ page }) => {
    await page.goto('/shop');
    const link = page.locator('a[href*="/shop/p/"]').first();
    await expect(link).toBeVisible({ timeout: 20_000 });
    await link.click();
    await expect(page).toHaveURL(/\/shop\/p\/[0-9a-f-]{36}$/);
    await expect(page.getByRole('heading', { level: 1 })).toBeVisible();
    await expect(page.getByText(/יחידת מכירה|מארזים/)).toHaveCount(0);
    await expect(page.getByRole('button', { name: /^הוספת יחידה — / })).toBeVisible();
    const qty = page.getByRole('button', { name: /^הוספת יחידה — / }).locator('xpath=following-sibling::*[1]');
    await expect(qty).toHaveText(/^\d+$/);
  });
});
